<?php require_once __DIR__.'/../auth.php'; require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST')redirect('index.php');$id=(int)($_POST['id']??0);$s=$conn->prepare('SELECT poster,title FROM events WHERE id=?');$s->bind_param('i',$id);$s->execute();$ev=$s->get_result()->fetch_assoc();$s->close();$d=$conn->prepare('DELETE FROM events WHERE id=?');$d->bind_param('i',$id);$d->execute();$d->close();if($ev&&$ev['poster']&&is_file(__DIR__.'/uploads/'.$ev['poster']))unlink(__DIR__.'/uploads/'.$ev['poster']);log_action($conn,(int)$_SESSION['student_id'],'event_delete',$ev['title']??('Event id '.$id));set_flash($ev?'Event deleted.':'Event not found.',$ev?'success':'error');redirect('index.php');
